// Development-only fresh native Tentacle MClientReconnect encoder and decoder.
// Pinned v20.2.4 commit 7f793731f1b39eb4f465e960113d2363c311b964.
// Ceph headers/library LGPL-2.1. Only public/native objects and encoders are
// invoked; no upstream implementation or socket/Go-generated bytes copied.
// Envelope projection and receipt helpers are adapted from the repository MDS
// capability wrapper; MClientReconnect carries its whole payload in the data
// segment, so this wrapper requires an empty front and middle.
//
// Messages are constructed the way Client::send_reconnect fills them on a
// CEPHFS_FEATURE_MULTI_RECONNECT session: a fresh make_message, add_cap per
// head inode with an Inode::make_short_path base and path, the
// Client::_encode_filelocks blob and the first pending cap snap, add_snaprealm
// once per realm, and mark_more on a split message. set_encoding_version(0)
// is never called, so the default HEAD_VERSION 5/COMPAT_VERSION 4 is encoded.
// Field values are explicit test inputs. The receipts report what separate
// default-constructed native objects decoded (including the flock blob as
// Server::recover_filelocks reads it), not the wrapper's input constants.
#include "messages/MClientReconnect.h"
#include "msg/async/frames_v2.h"
#include "include/ceph_features.h"
#include <cstdio>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <initializer_list>
#include <iostream>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>
namespace {
// MClientReconnect::encode_payload consults features only when the header
// version was reset to 0 (set_encoding_version(0)); at the default version 5
// they are ignored. These are the bits that would otherwise select v3.
constexpr uint64_t features = CEPH_FEATURE_FLOCK | CEPH_FEATURE_MDSENC;

void write_segment(const std::filesystem::path& path,
                   const ceph::buffer::list& segment) {
  const auto bytes = segment.to_str();
  std::ofstream out(path, std::ios::binary);
  out.exceptions(std::ios::failbit | std::ios::badbit);
  out.write(bytes.data(), bytes.size());
}

std::string hex(const std::string& bytes) {
  constexpr char digits[] = "0123456789abcdef";
  std::string out;
  for (unsigned char b : bytes) {
    out += digits[b >> 4];
    out += digits[b & 15];
  }
  return out;
}

std::string json_string(const std::string& value) {
  std::string out = "\"";
  for (unsigned char c : value) {
    if (c == '"' || c == '\\') {
      out += '\\';
      out += char(c);
    } else if (c < 0x20 || c >= 0x7f) {
      char escaped[8];
      std::snprintf(escaped, sizeof(escaped), "\\u%04x", unsigned(c));
      out += escaped;
    } else {
      out += char(c);
    }
  }
  return out + "\"";
}

// Minimal JSON builders for the decoder receipts.
std::string jnum(uint64_t v) { return std::to_string(v); }
std::string jhex(const std::string& bytes) { return json_string(hex(bytes)); }
std::string jbool(bool v) { return v ? "true" : "false"; }
std::string jkv(const std::string& key, const std::string& value) {
  return json_string(key) + ":" + value;
}
std::string jobj(std::initializer_list<std::string> fields) {
  std::string out = "{";
  bool first = true;
  for (const auto& f : fields) {
    out += (first ? "" : ",") + f;
    first = false;
  }
  return out + "}";
}
std::string jarr(const std::vector<std::string>& items) {
  std::string out = "[";
  for (size_t i = 0; i < items.size(); ++i)
    out += (i ? "," : "") + items[i];
  return out + "]";
}

void emit(const std::filesystem::path& root, const std::string& name,
          Message& message) {
  if (message.get_payload().length() != 0 ||
      message.get_middle().length() != 0 || message.get_data().length() != 0)
    throw std::runtime_error("fresh encoder input must have empty front, middle and data");
  message.set_seq(1);  // Explicit offline transport input, not live session state.
  message.set_priority(CEPH_MSG_PRIO_DEFAULT);
  // Invoke the canonical Message::encode path exactly once on a fresh object.
  // Its empty-payload branch dispatches the unchanged virtual encode_payload,
  // which fills only the data segment; the declared compat version 4 is
  // nonzero and kept. No decoded message or cached payload is reused.
  message.encode(features, MSG_CRC_ALL, true);
  const auto& header = message.get_header();
  const auto& footer = message.get_footer();
  if (message.get_type() != CEPH_MSG_CLIENT_RECONNECT || header.version != 5 ||
      header.compat_version != 4 || header.tid != 0)
    throw std::runtime_error("native canonical encoder did not select the expected envelope for " + name);
  if (header.front_len != message.get_payload().length() ||
      header.middle_len != message.get_middle().length() ||
      header.data_len != message.get_data().length())
    throw std::runtime_error("native envelope lengths disagree with payloads");
  if (message.get_payload().length() != 0 || message.get_middle().length() != 0 ||
      message.get_data().length() == 0)
    throw std::runtime_error("native MClientReconnect payload left the data segment for " + name);
  // Project the fresh native envelope into the native v2 struct, as required
  // by its public MessageFrame API. This does not execute ProtocolV2's live
  // write_message/session path. ACK sequence 3 is another explicit test input.
  ceph_msg_header2 header2{};
  header2.seq = header.seq;
  header2.tid = header.tid;
  header2.type = header.type;
  header2.priority = header.priority;
  header2.version = header.version;
  header2.data_off = header.data_off;
  header2.ack_seq = 3;
  header2.flags = footer.flags;
  header2.compat_version = header.compat_version;
  header2.reserved = header.reserved;
  auto frame = ceph::msgr::v2::MessageFrame::Encode(
      header2, message.get_payload(), message.get_middle(), message.get_data());
  ceph::buffer::list encoded_header;
  encoded_header.append(reinterpret_cast<const char*>(&frame.header()),
                        sizeof(frame.header()));
  if (encoded_header.length() != 41)
    throw std::runtime_error("native v2 message header size changed");
  write_segment(root / (name + ".header.bin"), encoded_header);
  std::ofstream metadata(root / (name + ".native-header.json"));
  metadata.exceptions(std::ios::failbit | std::ios::badbit);
  metadata << "{\"type\":" << uint16_t(header.type)
           << ",\"version\":" << uint16_t(header.version)
           << ",\"compat\":" << uint16_t(header.compat_version)
           << ",\"tid\":" << uint64_t(header.tid)
           << ",\"seq\":" << uint64_t(header.seq)
           << ",\"priority\":" << uint16_t(header.priority)
           << ",\"front_len\":" << uint32_t(header.front_len)
           << ",\"middle_len\":" << uint32_t(header.middle_len)
           << ",\"data_len\":" << uint32_t(header.data_len)
           << ",\"data_off\":" << uint16_t(header.data_off)
           << ",\"flags\":" << unsigned(footer.flags)
           << ",\"ack_seq\":" << uint64_t(frame.header().ack_seq)
           << ",\"reserved\":" << uint16_t(header.reserved) << "}\n";
  write_segment(root / (name + ".front.bin"), message.get_payload());
  write_segment(root / (name + ".middle.bin"), message.get_middle());
  write_segment(root / (name + ".data.bin"), message.get_data());
  std::cout << name << "\t" << message.get_payload().length() << "\t"
            << message.get_middle().length() << "\t"
            << message.get_data().length() << "\n";
}

void write_receipt(const std::filesystem::path& root, const std::string& name,
                   const std::string& receipt) {
  std::ofstream out(root / (name + ".decoded.json"));
  out.exceptions(std::ios::failbit | std::ios::badbit);
  out << receipt << "\n";
}

// Server::recover_filelocks: a signed fcntl lock count and raw ceph_filelock
// records, then the same for flock locks.
std::string locks_json(ceph::buffer::list::const_iterator& p) {
  using ceph::decode;
  int count;
  decode(count, p);
  if (count < 0)
    throw std::runtime_error("native filelock count is negative");
  std::vector<std::string> locks;
  for (int i = 0; i < count; ++i) {
    ceph_filelock lock;
    decode(lock, p);
    locks.push_back(jobj({jkv("start", jnum(lock.start)), jkv("length", jnum(lock.length)),
                          jkv("client", jnum(lock.client)), jkv("owner", jnum(lock.owner)),
                          jkv("pid", jnum(lock.pid)), jkv("type", jnum(lock.type))}));
  }
  return jarr(locks);
}

std::string cap_json(inodeno_t ino, const cap_reconnect_t& cap) {
  std::string fcntl = "[]", flock = "[]";
  if (cap.flockbl.length()) {
    auto p = cap.flockbl.cbegin();
    fcntl = locks_json(p);
    flock = locks_json(p);
    if (!p.end())
      throw std::runtime_error("native filelock blob left trailing bytes");
  }
  const auto& c = cap.capinfo;
  return jobj({jkv("ino", jnum(ino)),
               jkv("path", json_string(cap.path)),
               jkv("cap_id", jnum(c.cap_id)),
               jkv("wanted", jnum(c.wanted)),
               jkv("issued", jnum(c.issued)),
               jkv("snaprealm", jnum(c.snaprealm)),
               jkv("pathbase", jnum(c.pathbase)),
               jkv("flock_len", jnum(c.flock_len)),
               jkv("flockbl_hex", jhex(cap.flockbl.to_str())),
               jkv("snap_follows", jnum(cap.snap_follows)),
               jkv("fcntl_locks", fcntl),
               jkv("flock_locks", flock)});
}

// Decode the fresh source's data segment with a separate default-constructed
// native object, as the receiving Messenger hands it to decode_payload, and
// separately confirm the native field decoders consume the segment exactly.
void emit_reconnect(const std::filesystem::path& root, const std::string& name,
                    const ceph::ref_t<MClientReconnect>& source) {
  emit(root, name, *source);
  auto d = ceph::make_message<MClientReconnect>();
  d->set_header(source->get_header());
  d->set_data(source->get_data());
  d->decode_payload();
  {
    using ceph::decode;
    std::map<inodeno_t, cap_reconnect_t> caps;
    std::vector<snaprealm_reconnect_t> realms;
    bool more;
    auto p = source->get_data().cbegin();
    decode(caps, p);
    decode(realms, p);
    decode(more, p);
    if (!p.end())
      throw std::runtime_error("native reconnect data left trailing bytes for " + name);
  }
  if (d->caps.size() != source->caps.size() || d->realms.size() != source->realms.size() ||
      d->more != source->more || d->has_more() != source->has_more())
    throw std::runtime_error("native reconnect decode for " + name);
  for (auto s = source->caps.begin(), g = d->caps.begin(); s != source->caps.end(); ++s, ++g) {
    if (s->first != g->first || s->second.path != g->second.path ||
        std::memcmp(&s->second.capinfo, &g->second.capinfo, sizeof(g->second.capinfo)) != 0 ||
        s->second.snap_follows != g->second.snap_follows ||
        !s->second.flockbl.contents_equal(g->second.flockbl) ||
        g->second.capinfo.flock_len != g->second.flockbl.length())
      throw std::runtime_error("native reconnect cap decode for " + name);
  }
  for (size_t i = 0; i < d->realms.size(); ++i)
    if (std::memcmp(&d->realms[i].realm, &source->realms[i].realm, sizeof(d->realms[i].realm)) != 0)
      throw std::runtime_error("native reconnect realm decode for " + name);
  std::vector<std::string> caps, realms;
  for (const auto& [ino, cap] : d->caps)
    caps.push_back(cap_json(ino, cap));
  for (const auto& r : d->realms)
    realms.push_back(jobj({jkv("ino", jnum(r.realm.ino)), jkv("seq", jnum(r.realm.seq)),
                           jkv("parent", jnum(r.realm.parent))}));
  write_receipt(root, name, jobj({
      jkv("message_type", jnum(d->get_header().type)),
      jkv("version", jnum(d->get_header().version)),
      jkv("compat_version", jnum(d->get_header().compat_version)),
      jkv("tid", jnum(d->get_tid())),
      jkv("caps", jarr(caps)),
      jkv("realms", jarr(realms)),
      jkv("more", jbool(d->has_more()))}));
}

// ---------------------------------------------------------------- inputs

ceph_filelock filelock(uint64_t start, uint64_t length, uint64_t owner, uint64_t pid, uint8_t type) {
  ceph_filelock lock{};
  lock.start = start;
  lock.length = length;
  lock.client = 4100;
  lock.owner = owner;
  lock.pid = pid;
  lock.type = type;
  return lock;
}

// Client::_encode_filelocks layout: fcntl lock count and locks, then flock
// lock count and locks (one byte-range fcntl lock and one whole-file flock).
ceph::buffer::list flock_blob() {
  using ceph::encode;
  ceph::buffer::list bl;
  encode(unsigned(1), bl);
  encode(filelock(4096, 8192, 0x8888, 4242, CEPH_LOCK_SHARED), bl);
  encode(unsigned(1), bl);
  encode(filelock(0, 0, 0x9999, 4243, CEPH_LOCK_EXCL), bl);
  return bl;
}

const inodeno_t file_ino(0x10000000005);
const inodeno_t realm_dir_ino(0x10000000004);
const inodeno_t dir_ino(0x10000000003);
constexpr int file_issued = CEPH_CAP_PIN | CEPH_CAP_AUTH_SHARED | CEPH_CAP_LINK_SHARED |
                            CEPH_CAP_XATTR_SHARED | CEPH_CAP_FILE_SHARED | CEPH_CAP_FILE_CACHE |
                            CEPH_CAP_FILE_RD | CEPH_CAP_FILE_WR | CEPH_CAP_FILE_BUFFER;
constexpr int file_wanted = CEPH_CAP_FILE_RD | CEPH_CAP_FILE_WR | CEPH_CAP_FILE_CACHE | CEPH_CAP_FILE_BUFFER;
constexpr int dir_issued = CEPH_CAP_PIN | CEPH_CAP_AUTH_SHARED | CEPH_CAP_LINK_SHARED |
                           CEPH_CAP_FILE_SHARED;
constexpr int dir_wanted = CEPH_CAP_FILE_SHARED;
}  // namespace

int main(int argc, char** argv) {
  try {
    if (argc != 2)
      throw std::runtime_error("usage: native-mds-reconnect-encoder OUTPUT_DIR");
    const std::filesystem::path root(argv[1]);
    std::filesystem::create_directories(root);

    // Two head-inode caps added out of inode order (std::map reorders them),
    // with distinct cap IDs, wanted/issued masks, realms, path bases and
    // paths; the file holds fcntl and flock locks and a pending cap snap.
    // Each realm is added once, in first-seen order.
    auto two = ceph::make_message<MClientReconnect>();
    {
      ceph::buffer::list locks = flock_blob();
      two->add_cap(file_ino, 0x7002, realm_dir_ino, "data.bin", file_wanted, file_issued,
                   realm_dir_ino, snapid_t(9), locks);
      two->add_snaprealm(realm_dir_ino, snapid_t(9), inodeno_t(CEPH_INO_ROOT));
      ceph::buffer::list none;
      two->add_cap(dir_ino, 0x7001, inodeno_t(CEPH_INO_ROOT), "dir", dir_wanted, dir_issued,
                   inodeno_t(CEPH_INO_ROOT), snapid_t(0), none);
      two->add_snaprealm(inodeno_t(CEPH_INO_ROOT), snapid_t(3), inodeno_t(0));
    }
    emit_reconnect(root, "mds-reconnect-native-reconnect-two-caps", two);

    // A message split off by the multi-reconnect size limit: one cap, no
    // realm in this part, marked more.
    auto more = ceph::make_message<MClientReconnect>();
    {
      ceph::buffer::list none;
      more->add_cap(inodeno_t(0x10000000006), 0x7003, dir_ino, "notes.txt",
                    CEPH_CAP_FILE_RD | CEPH_CAP_FILE_CACHE,
                    CEPH_CAP_PIN | CEPH_CAP_FILE_SHARED | CEPH_CAP_FILE_CACHE | CEPH_CAP_FILE_RD,
                    inodeno_t(CEPH_INO_ROOT), snapid_t(0), none);
      more->mark_more();
    }
    emit_reconnect(root, "mds-reconnect-native-reconnect-more", more);

    // The final part with no caps left and one realm.
    auto empty = ceph::make_message<MClientReconnect>();
    empty->add_snaprealm(inodeno_t(CEPH_INO_ROOT), snapid_t(3), inodeno_t(0));
    emit_reconnect(root, "mds-reconnect-native-reconnect-empty", empty);
    return 0;
  } catch (const std::exception& error) {
    std::cerr << error.what() << "\n";
    return 1;
  }
}
